/** Correlation and trace identifiers attached to standard API responses. */
export interface ApiMeta {
  request_id: string;
  trace_id?: string;
}

/** Builds response metadata from the current request and optional active trace.
 * @param requestId Request-scoped ID generated by RequestContextModule.
 * @param traceId Active OpenTelemetry trace ID, when available.
 * @returns Metadata included in the standard response envelope.
 * @example `createApiMeta(requestId, traceId)`
 */
export function createApiMeta(requestId: string, traceId?: string): ApiMeta {
  return {
    request_id: requestId,
    ...(traceId ? { trace_id: traceId } : {}),
  };
}
